// Toma el lote más reciente y muestra su estado.
const lote = ($input.first().json.data || [])[0] || {};
return [{ json: {
  id_del_lote: lote.id,
  estado: lote.processing_status,
  results_url: lote.results_url,
  pedidos: lote.request_counts
} }];

// Los resultados vienen en formato JSONL: una línea por consulta.
// Pueden llegar en cualquier orden: por eso cada una trae su custom_id.
// Precios de lote de Claude Sonnet 5 por millón de tokens (la mitad de los normales):
// entrada 1 · escritura en caché de 1 hora 2 · lectura de caché 0,10 · salida 5
const texto = $input.first().json.data || '';
return texto.split('\n').filter(l => l.trim()).map(l => {
  const r = JSON.parse(l);
  const m = (r.result && r.result.message) || {};
  let datos = {};
  try {
    datos = JSON.parse((m.content || []).filter(b => b.type === 'text').map(b => b.text).join('')
      .replace(/```json|```/g, '').trim());
  } catch (e) {
    datos = {};
  }
  const u = m.usage || {};
  const costo = ((u.input_tokens || 0) * 1 + (u.cache_creation_input_tokens || 0) * 2
    + (u.cache_read_input_tokens || 0) * 0.1 + (u.output_tokens || 0) * 5) / 1000000;
  return { json: {
    custom_id: r.custom_id,
    resultado: r.result ? r.result.type : 'sin resultado',
    servicio: datos.servicio,
    presupuesto_usd: datos.presupuesto_usd,
    prioridad: datos.prioridad,
    resumen: datos.resumen,
    tokens_guardados_en_el_escritorio: u.cache_creation_input_tokens || 0,
    tokens_leidos_del_escritorio: u.cache_read_input_tokens || 0,
    tokens_del_correo: u.input_tokens || 0,
    tokens_de_la_respuesta: u.output_tokens || 0,
    costo_usd: Number(costo.toFixed(5))
  } };
});

return [{ json: {
  estado: $input.first().json.estado,
  mensaje: 'Todavía no terminó. Volvé a ejecutar este flujo en unos minutos.'
} }];
